# Helpers over the data above -------------------------------------------------
works_in <- function(term) Filter(function(w) w$term == term, WORKS)
for (i in seq_along(WORKS)) WORKS[[i]]$tab <- paste0("w_", WORKS[[i]]$id)
for (i in seq_along(WORKS)) WORKS[[i]]$file <- paste0("pdf/", WORKS[[i]]$id, ".pdf")
for (i in seq_along(WORKS)) WORKS[[i]]$pages_label <- sprintf("pp. %d\u2013%d", WORKS[[i]]$pages[1], WORKS[[i]]$pages[2])
for (i in seq_along(WORKS)) WORKS[[i]]$term_label <- TERMS[[which(sapply(TERMS, `[[`, "key") == WORKS[[i]]$term)]]$label
TERM_COL <- setNames(sapply(TERMS, `[[`, "colour"), sapply(TERMS, `[[`, "key"))
